subroutine FindLargest(data[] as integer by reference, index as integer, size as integer) as integer
    if index = size - 1 then
        return data[index];
    else
        define rest as integer;
        rest <- FindLargest(data, index + 1, size);
        if data[index] > rest then
            return data[index];
        else
            return rest;
        endIf
    endIf
endSubroutine

algorithm RunRecursiveLargest
    dimension numbers[5] as integer;
    read numbers[0];
    read numbers[1];
    read numbers[2];
    read numbers[3];
    read numbers[4];
    write FindLargest(numbers, 0, 5);
endAlgorithm
